// src/components/AiCompanion.js
import React, { useState } from 'react';
import styled from 'styled-components';

const CompanionContainer = styled.div`
  margin: 20px 0;
  padding: 20px;
  border-radius: 8px;
  background-color: #f0f8ff;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  max-width: 400px;
`;

const Message = styled.p`
  font-size: 1.2rem;
  margin-bottom: 15px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 10px;
`;

const Button = styled.button`
  flex: 1;
  padding: 12px;
  border-radius: 5px;
  border: none;
  cursor: pointer;

  ${({ yes }) =>
    yes
      ? `background-color: #4caf50; color: white;`
      : `background-color: #f44336; color: white;`}

  &:hover {
    opacity: 0.9;
  }
`;

const SummaryContainer = styled.div`
  background-color: #e8f5e9;
  padding: 15px;
  margin-top: 20px;
  border-radius: 5px;
  border: 1px solid #c8e6c9;
`;

const AiCompanion = ({ setPackagePrice }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({});
  const [summary, setSummary] = useState(null);

  const questions = [
    'Are you preparing for your first triathlon?',
    'Do you need a complete gear package?',
    'Do you prefer entry-level or advanced equipment?',
    'Do you have a specific budget in mind?',
  ];

  const handleYes = () => {
    const nextStep = step + 1;

    if (step === 3) {
      const userBudget = prompt('Enter your budget (in USD):');
      setPackagePrice(userBudget);
      setSummary(`Based on your budget of $${userBudget}, we'll find the best gear package.`);
    }

    setAnswers((prev) => ({ ...prev, [step]: 'Yes' }));
    setStep(nextStep);
  };

  const handleNo = () => {
    const nextStep = step + 1;
    setAnswers((prev) => ({ ...prev, [step]: 'No' }));
    setStep(nextStep);
  };

  const restartCompanion = () => {
    setStep(0);
    setAnswers({});
    setSummary(null);
  };

  return (
    <CompanionContainer>
      {step < questions.length ? (
        <>
          <Message>{questions[step]}</Message>
          <ButtonGroup>
            <Button yes onClick={handleYes}>
              Yes
            </Button>
            <Button onClick={handleNo}>No</Button>
          </ButtonGroup>
        </>
      ) : (
        <SummaryContainer>
          <h3>Summary</h3>
          <p>
            Based on your answers, we recommend:
            {answers[0] === 'Yes' && ' A beginner-friendly gear set.'}
            {answers[1] === 'Yes' && ' A complete gear package.'}
            {answers[2] === 'Yes'
              ? ' Advanced equipment for optimal performance.'
              : ' Affordable entry-level options to get started.'}
          </p>
          {summary && <p>{summary}</p>}
          <Button onClick={restartCompanion}>Restart</Button>
        </SummaryContainer>
      )}
    </CompanionContainer>
  );
};

export default AiCompanion;
